$search_endpoint = $lines[468..(from fastapi import APIRouter, Depends, HTTPException, UploadFile, File, Form, status from sqlalchemy.ext.asyncio import AsyncSession from sqlalchemy import select, update, and_, or_ from sqlalchemy.orm import selectinload from typing import List, Optional from datetime import datetime, timedelta import json import uuid  from app.database import get_db from app.models.orm import ContractMaster, ContractParameterExtracted, ContractAuditTrail from app.schemas.pydantic_models import (     ContractResponse, ParameterResponse, ParameterUpdate, LockAcquireRequest, LockResponse ) from app.services.ocr import extraction_engine  router = APIRouter(prefix="/contracts", tags=["Contracts Workflow"])   @router.post("/upload", response_model=ContractResponse, status_code=status.HTTP_202_ACCEPTED) async def upload_contract(     file: UploadFile = File(...),     organization: str = Form(...),     business_unit: str = Form(...),     contract_type: str = Form(...),     agreement_type: str = Form(...),     user_id: str = Form(...),     db: AsyncSession = Depends(get_db) ):     """     Ingests a contract document (PDF/Word/Excel), parses raw text, dynamically executes      the active parameters extraction rules engine, and inserts staged records into Oracle 23ai.     """     contract_id = f"CON-{uuid.uuid4().hex[:8].upper()}"          # Read file content (in production, run OCR or text parsing)     file_bytes = await file.read()     document_text = file_bytes.decode("utf-8", errors="ignore")     if not document_text.strip():         # Fallback text representation for simulated parsing         document_text = (             f"This is a simulated document text block for contract ID {contract_id}. "             "Section 1. SCOPE OF SERVICES: Provider will deliver standard operations cloud hosting. "             "Section 4. LIMITATION OF LIABILITY: Both parties limit aggregate liability to the sum of five million dollars ($5,000,000.00). "             "Section 9. TERMINATION: Mutual convenience termination is permitted upon providing 90 days written notice. "             "Section 11. GOVERNING LAW: Delaware USA."         )      # 1. Insert Master contract entry     new_contract = ContractMaster(         contract_id=contract_id,         organization=organization,         business_unit=business_unit,         contract_type=contract_type,         agreement_type=agreement_type,         workflow_state="STAGED_DRAFT",         document_version=1     )     db.add(new_contract)     await db.commit()      # 2. Asynchronously run AI Extraction Rules Engine     extracted_params = await extraction_engine.run_extraction_for_contract(         contract_type=contract_type,         agreement_type=agreement_type,         document_text=document_text     )      # 3. Save extracted details to Database     params_to_insert = []     for param in extracted_params:         db_param = ContractParameterExtracted(             contract_id=contract_id,             header_name=param["header_name"],             param_name=param["param_name"],             original_extract=param["original_extract"],             user_override=param["user_override"],             match_score=param["match_score"],             spatial_json=json.dumps(param["spatial_json"]) if isinstance(param["spatial_json"], dict) else param["spatial_json"],             vector_embed=param["vector_embed"]         )         db.add(db_param)         params_to_insert.append(db_param)      # 4. Create upload entry log in Audit Trail     audit_log = ContractAuditTrail(         contract_id=contract_id,         action_type="BATCH_ACCEPT_FORMATTING",         field_changed="MULTIPLE_FORMAT_PARAMETERS",         new_value_clob=json.dumps({"extracted_count": len(params_to_insert)}),         modified_by=user_id     )     db.add(audit_log)          await db.commit()     # Eagerly load parameters to prevent lazy loading MissingGreenlet error in serialization     result = await db.execute(         select(ContractMaster)         .options(selectinload(ContractMaster.parameters))         .where(ContractMaster.contract_id == contract_id)     )     new_contract = result.scalar_one()     return new_contract   @router.get("", response_model=List[ContractResponse]) async def list_contracts(     year: Optional[str] = None,     status: Optional[str] = None,     db: AsyncSession = Depends(get_db) ):     """     Returns an index list of ingested agreements matching filters.     """     query = select(ContractMaster).options(selectinload(ContractMaster.parameters))          conditions = []     if status and status != "All":         conditions.append(ContractMaster.workflow_state == status)              # Standard date filter logic if year is specified     if year and year != "Archive":         start_date = datetime(int(year), 1, 1)         end_date = datetime(int(year), 12, 31, 23, 59, 59)         conditions.append(and_(ContractMaster.last_updated >= start_date, ContractMaster.last_updated <= end_date))     elif year == "Archive":         archive_limit = datetime(2023, 1, 1)         conditions.append(ContractMaster.last_updated < archive_limit)      if conditions:         query = query.where(and_(*conditions))      result = await db.execute(query)     return result.scalars().all()   @router.get("/{id}", response_model=ContractResponse) async def get_contract_details(id: str, db: AsyncSession = Depends(get_db)):     """     Fetches detailed extraction records.     """     query = (         select(ContractMaster)         .options(selectinload(ContractMaster.parameters))         .where(ContractMaster.contract_id == id)     )     result = await db.execute(query)     contract = result.scalar_one_or_none()     if not contract:         raise HTTPException(status_code=404, detail="Contract not found.")     return contract   @router.post("/{id}/lock", response_model=LockResponse) async def acquire_lock(id: str, payload: LockAcquireRequest, db: AsyncSession = Depends(get_db)):     """     Implements standard Oracle 23ai 15-Minute checkout leasing.     Acquires lease if checked_out_by is null or checkout_expiry is in the past.     """     now = datetime.now()     expiry_time = now + timedelta(minutes=15)      # Atomic lease checkout update     stmt = (         update(ContractMaster)         .where(             and_(                 ContractMaster.contract_id == id,                 or_(                     ContractMaster.checked_out_by.is_(None),                     ContractMaster.checkout_expiry < now,                     ContractMaster.checked_out_by == payload.user_id                 )             )         )         .values(             checked_out_by=payload.user_id,             checkout_expiry=expiry_time         )     )          result = await db.execute(stmt)     await db.commit()      if result.rowcount == 0:         # Fetch current lock holder info         q = select(ContractMaster.checked_out_by, ContractMaster.checkout_expiry).where(ContractMaster.contract_id == id)         curr = await db.execute(q)         row = curr.first()         return LockResponse(             contract_id=id,             checked_out_by=row[0] if row else None,             checkout_expiry=str(row[1]) if row else None,             lock_acquired=False         )      return LockResponse(         contract_id=id,         checked_out_by=payload.user_id,         checkout_expiry=str(expiry_time),         lock_acquired=True     )   @router.post("/{id}/unlock", status_code=status.HTTP_200_OK) async def release_lock(id: str, payload: LockAcquireRequest, db: AsyncSession = Depends(get_db)):     """     Releases checked out locks.     """     stmt = (         update(ContractMaster)         .where(             and_(                 ContractMaster.contract_id == id,                 ContractMaster.checked_out_by == payload.user_id             )         )         .values(             checked_out_by=None,             checkout_expiry=None         )     )     await db.execute(stmt)     await db.commit()     return {"message": "Lock released."}   @router.put("/{id}/parameters/{param_id}", response_model=ParameterResponse) async def update_parameter_override(     id: str,      param_id: int,      payload: ParameterUpdate,      db: AsyncSession = Depends(get_db) ):     """     Applies overrides, incrementing document versions and logging actions inside Audit Trails.     """     # 1. Check lock lease authorization     q_contract = select(ContractMaster).where(ContractMaster.contract_id == id)     c_res = await db.execute(q_contract)     contract = c_res.scalar_one_or_none()          if not contract:         raise HTTPException(status_code=404, detail="Contract not found.")          if contract.checked_out_by != payload.modified_by:          raise HTTPException(              status_code=403,               detail=f"Resource is locked by lease holder: {contract.checked_out_by}"          )      # 2. Locate active parameter record     q_param = select(ContractParameterExtracted).where(         and_(             ContractParameterExtracted.parameter_id == param_id,             ContractParameterExtracted.contract_id == id         )     )     p_res = await db.execute(q_param)     parameter = p_res.scalar_one_or_none()          if not parameter:         raise HTTPException(status_code=404, detail="Parameter record not found.")      old_val = parameter.user_override     new_val = payload.user_override      # 3. Update override and versions     parameter.user_override = new_val     contract.document_version += 1          # 4. Ledger transaction logs inside Audit Trail     audit_trail = ContractAuditTrail(         contract_id=id,         action_type="HUMAN_EDIT",         field_changed=parameter.header_name,         old_value_clob=old_val,         new_value_clob=new_val,         modified_by=payload.modified_by     )     db.add(audit_trail)          await db.commit()     await db.refresh(parameter)     return parameter   @router.post("/{id}/submit-draft", status_code=status.HTTP_200_OK) async def submit_draft(id: str, db: AsyncSession = Depends(get_db)):     """     Submits active workspace parameters as staged drafts.     """     stmt = update(ContractMaster).where(ContractMaster.contract_id == id).values(workflow_state="STAGED_DRAFT")     await db.execute(stmt)     await db.commit()     return {"message": "Draft workspace saved."}   @router.post("/{id}/submit-approval", status_code=status.HTTP_200_OK) async def submit_for_approval(id: str, db: AsyncSession = Depends(get_db)):     """     Submits contract parameters to operation manager for review.     """     stmt = update(ContractMaster).where(ContractMaster.contract_id == id).values(workflow_state="PENDING_APPROVAL")     await db.execute(stmt)     await db.commit()     return {"message": "Submitted to Approval queue."}   @router.post("/{id}/approve", status_code=status.HTTP_200_OK) async def approve_contract(id: str, db: AsyncSession = Depends(get_db)):     """     Finalizes and signs parameters entries in active production log.     """     stmt = update(ContractMaster).where(ContractMaster.contract_id == id).values(workflow_state="APPROVED")     await db.execute(stmt)     await db.commit()     return {"message": "Contract finalized and approved."}   @router.post("/{id}/reject", status_code=status.HTTP_200_OK) async def reject_contract(id: str, db: AsyncSession = Depends(get_db)):     """     Sends contract back to operational draft modes.     """     stmt = update(ContractMaster).where(ContractMaster.contract_id == id).values(workflow_state="STAGED_DRAFT")     await db.execute(stmt)     await db.commit()     return {"message": "Contract rejected and returned to Draft."}   @router.get("/{id}/compare", status_code=status.HTTP_200_OK) async def compare_versions(id: str, compare_to_id: str, db: AsyncSession = Depends(get_db)):     """     Compares two contracts or versions side-by-side to highlight differences.     """     q1 = select(ContractParameterExtracted).where(ContractParameterExtracted.contract_id == id)     q2 = select(ContractParameterExtracted).where(ContractParameterExtracted.contract_id == compare_to_id)          r1 = await db.execute(q1)     r2 = await db.execute(q2)          params1 = r1.scalars().all()     params2 = r2.scalars().all()      comparison = []     for p1 in params1:         # Match parameter name         p2 = next((p for p in params2 if p.header_name == p1.header_name), None)         comparison.append({             "parameter": p1.header_name,             "original_value": p1.user_override,             "compared_value": p2.user_override if p2 else None,             "modified": p1.user_override != (p2.user_override if p2 else None)         })              return comparison   @router.post("/{id}/clone", response_model=ContractResponse, status_code=status.HTTP_201_CREATED) async def clone_contract_template(id: str, new_user_id: str, db: AsyncSession = Depends(get_db)):     """     Clones verified parameters from the latest approved contract template to initialize a new form.     """     query = select(ContractMaster).where(ContractMaster.contract_id == id)     result = await db.execute(query)     source = result.scalar_one_or_none()     if not source:         raise HTTPException(status_code=404, detail="Source contract not found.")      clone_id = f"CON-{uuid.uuid4().hex[:8].upper()}"     cloned_master = ContractMaster(         contract_id=clone_id,         organization=source.organization,         business_unit=source.business_unit,         contract_type=source.contract_type,         agreement_type=source.agreement_type,         workflow_state="STAGED_DRAFT",         document_version=1     )     db.add(cloned_master)     await db.commit()      # Query source params     q_params = select(ContractParameterExtracted).where(ContractParameterExtracted.contract_id == id)     p_res = await db.execute(q_params)     source_params = p_res.scalars().all()      for p in source_params:         db_param = ContractParameterExtracted(             contract_id=clone_id,             header_name=p.header_name,             param_name=p.param_name,             original_extract=p.user_override, # Use approved override value as baseline             user_override=p.user_override,             match_score=p.match_score,             spatial_json=p.spatial_json,             vector_embed=p.vector_embed         )         db.add(db_param)      # Log clone action     audit_log = ContractAuditTrail(         contract_id=clone_id,         action_type="CLONE_TEMPLATE",         field_changed="TEMPLATE_SOURCE",         old_value_clob=id,         modified_by=new_user_id     )     db.add(audit_log)     await db.commit()     # Eagerly load parameters to prevent lazy loading MissingGreenlet error in serialization     result = await db.execute(         select(ContractMaster)         .options(selectinload(ContractMaster.parameters))         .where(ContractMaster.contract_id == clone_id)     )     cloned_master = result.scalar_one()     return cloned_master   # ===== ADDITIONAL ENDPOINTS =====  @router.get("/{id}/audit", status_code=status.HTTP_200_OK) async def get_audit_trail(     id: str,     db: AsyncSession = Depends(get_db) ):     """Get complete audit trail for a contract"""     result = await db.execute(         select(ContractAuditTrail)         .where(ContractAuditTrail.contract_id == id)         .order_by(ContractAuditTrail.timestamp.desc())     )     audits = result.scalars().all()     return {"contract_id": id, "audit_trail": [{"action": a.action_type, "timestamp": a.timestamp.isoformat() if a.timestamp else None} for a in audits]}   @router.get("/{id}/parameters", status_code=status.HTTP_200_OK) async def get_parameters(     id: str,     db: AsyncSession = Depends(get_db) ):     """Get all parameters for a contract"""     result = await db.execute(         select(ContractParameterExtracted)         .where(ContractParameterExtracted.contract_id == id)     )     parameters = result.scalars().all()     return {"contract_id": id, "parameters": [ParameterResponse.from_orm(p).__dict__ for p in parameters]}   @router.get("/{id}/extraction-status", status_code=status.HTTP_200_OK) async def get_extraction_status(     id: str,     db: AsyncSession = Depends(get_db) ):     """Get extraction status for a contract"""     result = await db.execute(         select(ContractMaster).where(ContractMaster.contract_id == id)     )     contract = result.scalar_one_or_none()     if not contract:         raise HTTPException(status_code=404, detail="Contract not found")          return {"contract_id": id, "status": contract.workflow_state, "parameters_extracted": len(contract.parameters)}   @router.get("/search", status_code=status.HTTP_200_OK) async def search_contracts(     q: str = None,     organization: str = None,     business_unit: str = None,     contract_type: str = None,     agreement_type: str = None,     db: AsyncSession = Depends(get_db) ):     """Search contracts by query and filters"""     query = select(ContractMaster)          if q:         query = query.where(or_(             ContractMaster.contract_id.like(f"%{q}%"),             ContractMaster.organization.like(f"%{q}%")         ))     if organization:         query = query.where(ContractMaster.organization == organization)     if business_unit:         query = query.where(ContractMaster.business_unit == business_unit)     if contract_type:         query = query.where(ContractMaster.contract_type == contract_type)     if agreement_type:         query = query.where(ContractMaster.agreement_type == agreement_type)          result = await db.execute(query)     contracts = result.scalars().all()     return {"results": [ContractResponse.from_orm(c).__dict__ for c in contracts]} .Count-1)]

